-- ══════════════════════════════════════════════════════════════════
-- EnglishUp · Giáo trình  (giaotrinh.html)
-- Tạo 3 bảng: curricula → curriculum_units → curriculum_topics
-- Nạp sẵn giáo trình "Oxford PVD — Chủ đề đời sống": 12 nhóm · 128 chủ đề
-- CHẠY LẠI ĐƯỢC NHIỀU LẦN (ON CONFLICT DO UPDATE), không đụng bảng words
-- ══════════════════════════════════════════════════════════════════

create table if not exists curricula (
  code          text primary key,
  title         text not null,
  subtitle      text,
  description   text,
  cover_emoji   text default '📘',
  color         text default '#4f8ef7',
  level_range   text,
  n_units       int  default 0,
  n_topics      int  default 0,
  target_words  int  default 0,
  status        text default 'ready',      -- ready | draft | soon
  ord           int  default 0,
  version       text,
  note          text,
  created_at    timestamptz default now()
);

create table if not exists curriculum_units (
  code             text primary key,
  curriculum_code  text not null references curricula(code) on delete cascade,
  no               int,
  name_en          text,
  name_vi          text,
  note             text,
  n_topics         int,
  target_words     int,
  cefr             text[]
);
create index if not exists idx_cu_curr on curriculum_units(curriculum_code);

create table if not exists curriculum_topics (
  code             text primary key,
  unit_code        text not null references curriculum_units(code) on delete cascade,
  curriculum_code  text not null,
  ord              int,
  name_en          text,
  name_vi          text,
  cefr             text,
  target_words     int,
  objective        text,
  focus            text[],
  pattern          text,
  image_brief      text,
  prompts          text[],
  word_terms       text[],   -- (tuỳ chọn) danh sách từ lấy từ bảng words khi words.topic_code chưa có
  image_url        text
);
create index if not exists idx_ct_unit on curriculum_topics(unit_code);
create index if not exists idx_ct_curr on curriculum_topics(curriculum_code);

-- ── Bổ sung cột nếu bảng đã tồn tại từ lần chạy trước ──────────────
alter table curricula          add column if not exists note text;
alter table curriculum_topics  add column if not exists word_terms text[];
alter table curriculum_topics  add column if not exists image_url text;

-- ── RLS: đọc công khai, ghi bằng anon key (đúng quy ước sẵn có) ────
alter table curricula enable row level security;
drop policy if exists "curricula_all" on curricula;
create policy "curricula_all" on curricula for all using (true) with check (true);
alter table curriculum_units enable row level security;
drop policy if exists "curriculum_units_all" on curriculum_units;
create policy "curriculum_units_all" on curriculum_units for all using (true) with check (true);
alter table curriculum_topics enable row level security;
drop policy if exists "curriculum_topics_all" on curriculum_topics;
create policy "curriculum_topics_all" on curriculum_topics for all using (true) with check (true);

-- ══════════════ 1. DANH MỤC GIÁO TRÌNH ══════════════
on conflict (code) do update set
  "title"=excluded."title",
  "subtitle"=excluded."subtitle",
  "description"=excluded."description",
  "cover_emoji"=excluded."cover_emoji",
  "color"=excluded."color",
  "level_range"=excluded."level_range",
  "n_units"=excluded."n_units",
  "n_topics"=excluded."n_topics",
  "target_words"=excluded."target_words",
  "status"=excluded."status",
  "ord"=excluded."ord",
  "version"=excluded."version",
  "note"=excluded."note";

-- ══════════════ 2. NHÓM CHỦ ĐỀ (12) ══════════════
on conflict (code) do update set
  "curriculum_code"=excluded."curriculum_code",
  "no"=excluded."no",
  "name_en"=excluded."name_en",
  "name_vi"=excluded."name_vi",
  "note"=excluded."note",
  "n_topics"=excluded."n_topics",
  "target_words"=excluded."target_words",
  "cefr"=excluded."cefr";

-- ══════════════ 3. CHỦ ĐỀ (128) ══════════════
on conflict (code) do update set
  "unit_code"=excluded."unit_code",
  "curriculum_code"=excluded."curriculum_code",
  "ord"=excluded."ord",
  "name_en"=excluded."name_en",
  "name_vi"=excluded."name_vi",
  "cefr"=excluded."cefr",
  "target_words"=excluded."target_words",
  "objective"=excluded."objective",
  "focus"=excluded."focus",
  "pattern"=excluded."pattern",
  "image_brief"=excluded."image_brief",
  "prompts"=excluded."prompts";

-- ══════════════ 4. KIỂM TRA ══════════════
select (select count(*) from curricula) as so_giao_trinh,
       (select count(*) from curriculum_units where curriculum_code='CDS') as so_nhom,
       (select count(*) from curriculum_topics where curriculum_code='CDS') as so_chu_de;
